'use strict';
// Actual Electron main process, no window, network, worker handoff or system writes.
const {app}=require('electron'),raw=require('original-fs'),fs=raw.promises,path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const root=process.argv.at(-1);if(!path.isAbsolute(root)||raw.lstatSync(root).isSymbolicLink())throw Error('Private fixture root required');app.setPath('userData',path.join(root,'data'));
const hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
function zip(entries){let offset=0;const local=[],central=[];for(const e of entries){const name=Buffer.from(e.name),data=Buffer.from(e.data),h=Buffer.alloc(30),c=Buffer.alloc(46);let crc=0xffffffff;for(const byte of data){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}crc=(crc^0xffffffff)>>>0;h.writeUInt32LE(0x04034b50);h.writeUInt16LE(20,4);h.writeUInt16LE(0x800,6);h.writeUInt32LE(crc,14);h.writeUInt32LE(data.length,18);h.writeUInt32LE(data.length,22);h.writeUInt16LE(name.length,26);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(0x314,4);c.writeUInt16LE(20,6);c.writeUInt16LE(0x800,8);c.writeUInt32LE(crc,16);c.writeUInt32LE(data.length,20);c.writeUInt32LE(data.length,24);c.writeUInt16LE(name.length,28);c.writeUInt32LE((0o100644*65536)>>>0,38);c.writeUInt32LE(offset,42);local.push(h,name,data);central.push(c,name);offset+=h.length+name.length+data.length;}const cd=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(cd.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...local,cd,end]);}
async function run(){
 const patched=require('node:fs'),valid=await fs.readFile(path.join(process.resourcesPath,'default_app.asar')),opaque=Buffer.from('opaque archive bytes\0\xff'),probe=path.join(root,'default_app.asar');await fs.writeFile(probe,valid);assert.equal(patched.lstatSync(probe).isDirectory(),true,'actual Electron ASAR virtualization must be active');assert.equal(raw.lstatSync(probe).isFile(),true);await assert.rejects(patched.promises.open(path.join(root,'baseline-missing.asar'),'wx'),/Invalid package/,'ordinary Electron fs reproduces the CI extraction error for a new ASAR file');
 const updater=require('../../src/core/updater.cjs'),acceptance=require('../../src/core/update-desktop-acceptance.cjs'),install=require('../../src/core/update-install.cjs');assert.equal(await updater.hashFile(probe),hash(valid));assert.equal(await acceptance.digest(probe),hash(valid));assert.equal(acceptance.privatePath(root,probe,{kind:'file'}),probe);const downloaded=path.join(root,'http.asar');await require('../../src/core/http.cjs').download(async()=>({ok:true,body:new ReadableStream({start(controller){controller.enqueue(opaque);controller.close();}})}),{url:'https://fixture.invalid/not-requested',size:opaque.length},downloaded);assert.deepEqual(await fs.readFile(downloaded),opaque);
 const pe=Buffer.alloc(512);pe.write('MZ');pe.writeUInt32LE(128,60);pe.write('PE\0\0',128);pe.writeUInt16LE(0x8664,132);pe.writeUInt16LE(2,150);const appPath=path.join(root,'installed'),dataDir=path.join(root,'data');await fs.mkdir(path.join(appPath,'resources/app'),{recursive:true});await fs.writeFile(path.join(appPath,'LaoyuNetTools.exe'),pe);await fs.writeFile(path.join(appPath,'resources/app/package.json'),JSON.stringify({name:'laoyu-nettools',version:'5.0.0',main:'src/main.cjs'}));
 const entries=[{name:'LaoyuNetTools.exe',data:pe},{name:'resources/app/package.json',data:JSON.stringify({name:'laoyu-nettools',version:'5.0.1',main:'src/main.cjs'})},...['src/main.cjs','scripts/update-mac.sh','scripts/update-win.ps1'].map(name=>({name:'resources/app/'+name,data:'// private fixture'})),{name:'resources/default_app.asar',data:valid},{name:'resources/extra.asar',data:opaque}],bytes=zip(entries),file=path.join(root,'source.zip');await fs.writeFile(file,bytes);const ready=await install.prepareUpdate({file,version:'5.0.1',name:'nettools-5.0.1-win-x64.zip',size:bytes.length,sha256:hash(bytes)},{appPath,dataDir,platform:'win32',arch:'x64'}),payload=JSON.parse(await fs.readFile(ready.payloadFile,'utf8'));
 for(const entry of entries.filter(e=>e.name.endsWith('.asar'))){const expected=Buffer.from(entry.data),row=payload.manifest.find(row=>row.path===entry.name);assert.deepEqual(row,{path:entry.name,kind:'file',size:expected.length,sha256:hash(expected)});assert.deepEqual(await fs.readFile(path.join(payload.stage,entry.name)),expected);assert.ok(!payload.manifest.some(row=>row.path.startsWith(entry.name+'/')));}
 assert.equal(JSON.parse(await fs.readFile(path.join(appPath,'resources/app/package.json'),'utf8')).version,'5.0.0');await assert.rejects(install.prepareUpdate({file,version:'5.0.1',name:'nettools-5.0.1-win-x64.zip',size:bytes.length,sha256:'0'.repeat(64)},{appPath,dataDir,platform:'win32',arch:'x64'}),/SHA|校验/);await install.abortUpdate(ready);console.log(JSON.stringify({electron:process.versions.electron,virtualizationActive:true,rawAsarFiles:2,asarManifest:payload.manifest.filter(row=>row.path.endsWith('.asar')),manifestHashesExact:true,originalVersionPreserved:true,wrongHashRejected:true}));
}
app.whenReady().then(run).then(()=>app.exit(0),error=>{console.error(error.stack||error);app.exit(1);});
